uniform float speed : 0.0 .. 10.0 = 1.0;
uniform float density : 0.01 .. 1.0 = 0.2;
uniform vec3 tint : color = 0.0, 0.8, 0.0;
state fixed ph;
void update() {
  ph = fract(ph + fixed(dt) * fixed(speed));
}
vec3 shade(Led led) {
  fixed d = fixed(led.dist);
  fixed h = fixed(led.pos.y) / fixed(0.30);
  fixed phase = fract(d + ph);
  fixed drop = smoothstep(fixed(0.0), fixed(0.05), phase);
  fixed rain = mix(fixed(0.0), fixed(1.0), step(density, phase));
  fixed g = mix(tint.x, tint.y, rain);
  fixed b = mix(tint.y, tint.z, rain);
  return vec3(g, g, b) * drop;
}
